#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
STAMP="$(date +%Y%m%d_%H%M%S)"
BK=".companyos_backups/pid_targeted_stop_v25_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/runtime_control.py "$BK/"
cp -a companyos/runtime/service_supervisor.py "$BK/"
echo "" | base64 -d > "$PREFIX/tmp/companyos_v25_patch.py"
python "$PREFIX/tmp/companyos_v25_patch.py"
rm -f "$PREFIX/tmp/companyos_v25_patch.py"
echo "" | base64 -d > scripts/companyos_verify_pid_targeted_stop_v25
chmod +x scripts/companyos_verify_pid_targeted_stop_v25
scripts/companyos_verify_pid_targeted_stop_v25 | tee .companyos_runtime/pid_targeted_stop_v25.log
git add companyos/runtime/runtime_control.py companyos/runtime/service_supervisor.py scripts/companyos_verify_pid_targeted_stop_v25
git diff --cached --quiet || git commit -m "Complete PID-targeted supervisor stop hardening"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true
echo "BACKUP=$BK"
echo "COMPANYOS_PID_TARGETED_STOP_REPAIR_V25=PASS"
